// src/components/Contacto.js
import React from 'react';
import './Contacto.css';

const Contacto = () => {
  return (
    <section id="contacto">
      <h2>Contacto</h2>
      <p>Si tienes alguna duda o deseas más información, no dudes en ponerte en contacto con nosotros.</p>
    </section>
  );
};

export default Contacto;
